# Generated by scripts/release.sh from packaging/squeeze.rb.template in rikinshah86/squeeze.
# Edit the template there, not this file.
class Squeeze < Formula
  desc "Compress PDFs and images from the command-line, Finder or a small app"
  homepage "https://github.com/rikinshah86/squeeze"
  url "https://github.com/rikinshah86/squeeze/archive/refs/tags/v0.1.0.tar.gz"
  sha256 "506e0d38c3a471d88bc19bb217a6c40b96de81fcb91d3d1b5f0f5c272dc0acef"
  license "MIT"

  depends_on "ghostscript"
  depends_on macos: :ventura
  depends_on "pngquant"

  def install
    # Homebrew's build sandbox clashes with SwiftPM's own, hence --disable-sandbox.
    system "make", "install-files", "PREFIX=#{prefix}", "SWIFT_FLAGS=--disable-sandbox"
  end

  def caveats
    <<~EOS
      To add Squeeze.app to ~/Applications and Squeeze's actions to Finder's
      right-click menu, run:
        squeeze setup-finder
      Run it again after each `brew upgrade squeeze`.
    EOS
  end

  test do
    assert_equal version.to_s, shell_output("#{bin}/squeeze --version").strip
    (testpath/"notes.txt").write "not an image"
    assert_match "skipped: not a PDF, JPEG, PNG or HEIC", shell_output("#{bin}/squeeze #{testpath}/notes.txt")
  end
end
